package main

import (
	"sync"
	"testing"
	"time"

	"github.com/beego/beego/v2/client/orm"
	_ "github.com/mattn/go-sqlite3"
)

var dbOnce sync.Once

func initDB() {
	dbOnce.Do(func() {
		defer func() { recover() }()
		orm.RegisterDriver("sqlite3", orm.DRSqlite)
		orm.RegisterDataBase("default", "sqlite3", "file::memory:?cache=shared")
		orm.RegisterModel(new(Candidate), new(JobPosting))
	})
}

func resetDB(o orm.Ormer) {
	o.Raw("DROP TABLE IF EXISTS job_posting").Exec()
	o.Raw("DROP TABLE IF EXISTS candidate").Exec()
	orm.RunSyncdb("default", true, false)
}

func setupRecruitmentData(o orm.Ormer) {
	now := time.Now()
	candidates := []struct {
		email, fullName, title, skills, location, education, summary, status string
		experience                                                           int
	}{
		{"alice@example.com", "Alice Johnson", "Senior Developer", "golang,python,java", "New York", "MIT", "Experienced backend developer", "active", 8},
		{"bob@example.com", "Bob Smith", "Full Stack Developer", "javascript,react,node", "San Francisco", "Stanford", "Frontend specialist", "active", 5},
		{"carol@example.com", "Carol_Williams", "Data Scientist", "python,ml,tensorflow", "Boston", "Harvard", "ML expert with 100% project success rate", "active", 6},
		{"dave@example.com", "Dave Brown", "DevOps Engineer", "docker,kubernetes,aws", "Seattle", "UW", "Cloud infrastructure specialist", "inactive", 4},
		{"eve@example.com", "Eve_Davis", "Java_Developer", "java,spring,hibernate", "Austin", "UT Austin", "Enterprise Java developer", "active", 7},
	}
	for _, c := range candidates {
		o.Raw("INSERT INTO candidate (email, full_name, title, skills, experience_years, location, education, summary, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
			c.email, c.fullName, c.title, c.skills, c.experience, c.location, c.education, c.summary, c.status, now).Exec()
	}

	jobs := []struct {
		code, title, department, requirements, location, salary, status string
	}{
		{"JOB001", "Senior Go Developer", "Engineering", "5+ years golang, kubernetes", "New York", "$150k-$200k", "open"},
		{"JOB002", "Data Engineer", "Data", "python, spark, sql", "Remote", "$130k-$170k", "open"},
		{"JOB003", "Frontend Developer", "Engineering", "react, typescript, css", "San Francisco", "$120k-$160k", "closed"},
	}
	for _, j := range jobs {
		o.Raw("INSERT INTO job_posting (job_code, title, department, requirements, location, salary_range, status, posted_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
			j.code, j.title, j.department, j.requirements, j.location, j.salary, j.status, now).Exec()
	}
}

// ==================== Functional Tests ====================

func TestFuncSearchCandidatesContains(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	results, err := SearchCandidates(o, "Developer", "title", "contains", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) < 2 {
		t.Errorf("expected at least 2 results, got %d", len(results))
	}
}

func TestFuncSearchCandidatesStartsWith(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	results, err := SearchCandidates(o, "Senior", "title", "startswith", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 1 {
		t.Errorf("expected 1 result, got %d", len(results))
	}
}

func TestFuncSearchCandidatesBySkills(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	candidates, err := SearchCandidatesBySkills(o, "python", 5)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(candidates) < 1 {
		t.Errorf("expected at least 1 candidate with python skills")
	}
}

func TestFuncSearchJobPostings(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	jobs, err := SearchJobPostings(o, "Developer", "title", "contains", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(jobs) < 2 {
		t.Errorf("expected at least 2 jobs, got %d", len(jobs))
	}
}

func TestFuncAutocompleteCandidates(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	suggestions, err := AutocompleteCandidates(o, "Ali", "full_name", 5)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(suggestions) == 0 {
		t.Error("expected some suggestions for 'Ali'")
	}
}

func TestFuncSearchByLocation(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	candidates, err := SearchByLocation(o, "New")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(candidates) != 1 {
		t.Errorf("expected 1 candidate in New York, got %d", len(candidates))
	}
}

func TestFuncAdvancedSearch(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	candidates, err := AdvancedCandidateSearch(o, "", "Developer", 5, "active")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(candidates) == 0 {
		t.Error("expected some candidates")
	}
}

