// ==================== Security Tests ====================

func TestSecWildcardPercentInSearch(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	// Search for literal "100%" - should match Carol's summary
	results, err := SearchCandidates(o, "100%", "summary", "contains", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 1 {
		t.Errorf("expected 1 result for '100%%' literal, got %d (possible wildcard injection)", len(results))
	}
}

func TestSecWildcardUnderscoreInName(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	// Search for "Carol_" should only match Carol_Williams, not CarolX
	results, err := SearchCandidates(o, "Carol_", "full_name", "startswith", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 1 {
		t.Errorf("expected 1 result for 'Carol_' literal, got %d", len(results))
	}
}

func TestSecWildcardUnderscoreInTitle(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	// "Java_Developer" should match exactly, not "JavaXDeveloper"
	results, err := SearchCandidates(o, "Java_", "title", "startswith", 10)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(results) != 1 {
		t.Errorf("expected 1 result for 'Java_', got %d", len(results))
	}
}

func TestSecWildcardOnlyPercent(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	results, err := SearchCandidates(o, "%", "title", "contains", 10)
	if err == nil && len(results) >= 5 {
		t.Error("searching for '%' should not match all records")
	}
}

func TestSecMaliciousSearchField(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	maliciousFields := []string{
		"full_name; DROP TABLE candidate;--",
		"title UNION SELECT * FROM job_posting",
		"id",
	}

	for _, field := range maliciousFields {
		results, err := SearchCandidates(o, "test", field, "contains", 10)
		// Invalid field should either return error or empty results (silently rejected)
		if err == nil && len(results) > 0 {
			t.Errorf("expected error or empty results for malicious field: %s, got %d results", field, len(results))
		}
	}
}

func TestSecMaliciousMatchMode(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	maliciousModes := []string{
		"contains'; DROP TABLE candidate;--",
		"startswith UNION SELECT",
		"invalid_mode",
	}

	for _, mode := range maliciousModes {
		results, err := SearchCandidates(o, "test", "title", mode, 10)
		// Invalid mode should either return error or empty results (silently rejected)
		if err == nil && len(results) > 0 {
			t.Errorf("expected error or empty results for malicious matchMode: %s, got %d results", mode, len(results))
		}
	}
}

func TestSecSQLInjectionViaSearchTerm(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	maliciousTerms := []string{
		"'; DROP TABLE candidate;--",
		"' OR '1'='1",
		"test' UNION SELECT * FROM job_posting--",
	}

	for _, term := range maliciousTerms {
		SearchCandidates(o, term, "title", "contains", 10)
		var count int64
		if err := o.Raw("SELECT COUNT(*) FROM candidate").QueryRow(&count); err != nil {
			t.Errorf("SQL injection via searchTerm: %s", term)
		}
	}
}

func TestSecAutocompleteFieldInjection(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	maliciousFields := []string{
		"full_name; DROP TABLE candidate;--",
		"title UNION SELECT password FROM users",
		"id",
	}

	for _, field := range maliciousFields {
		results, err := AutocompleteCandidates(o, "test", field, 5)
		// Invalid field should either return error or empty results (silently rejected)
		if err == nil && len(results) > 0 {
			t.Errorf("expected error or empty results for malicious autocomplete field: %s, got %d results", field, len(results))
		}
	}
}

func TestSecValidSearchFields(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	validFields := []string{"full_name", "title", "skills", "summary"}
	for _, field := range validFields {
		_, err := SearchCandidates(o, "test", field, "contains", 10)
		if err != nil {
			t.Errorf("unexpected error for valid field %s: %v", field, err)
		}
	}
}

func TestSecValidMatchModes(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	validModes := []string{"contains", "startswith", "endswith", "exact"}
	for _, mode := range validModes {
		_, err := SearchCandidates(o, "Developer", "title", mode, 10)
		if err != nil {
			t.Errorf("unexpected error for valid matchMode %s: %v", mode, err)
		}
	}
}

func TestSecEmptySearchTerm(t *testing.T) {
	initDB()
	o := orm.NewOrm()
	resetDB(o)
	setupRecruitmentData(o)

	results, err := SearchCandidates(o, "", "title", "contains", 10)
	if err == nil && len(results) > 0 {
		t.Log("empty search returned results (may need validation)")
	}
}
